WITH joined AS (SELECT e.id, e.store_id, e.product_id, e.units, b.brand, b.cost FROM store_sales e INNER JOIN products b ON e.product_id = b.id) SELECT CASE WHEN units >= 35 THEN 'PREMIUM' ELSE 'STANDARD' END AS units_tier, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(*) FILTER (WHERE brand = 'Acme') AS acme_rows, BIT_AND(units) AS units_bit_and, ROUND(AVG(units), 2) AS avg_units, GROUPING_ID() AS grouping_id FROM joined GROUP BY ROLLUP (CASE WHEN units >= 35 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY acme_rows DESC;
